-- Update dict_brand based on Excel 集团vs厂号.xlsx
-- Generated by Claude Code

BEGIN;

-- Step 1: Create temp table with Excel data
DROP TABLE IF EXISTS tmp_excel_brand;
CREATE TEMP TABLE tmp_excel_brand (
    factory_no VARCHAR(50),
    brand_name VARCHAR(255),
    alias_list VARCHAR(255)
);


-- Step 2: Update dict_brand for factories that ARE in Excel
UPDATE dict_brand db
SET brand_name = te.brand_name,
    alias_list = te.alias_list
FROM tmp_excel_brand te
JOIN dict_factory df ON db.factory_id = df.factory_id
WHERE te.factory_no = df.factory_no;

-- Step 3: Delete dict_brand records for factories NOT in Excel
DELETE FROM dict_brand db
WHERE NOT EXISTS (
    SELECT 1 FROM tmp_excel_brand te
    JOIN dict_factory df ON db.factory_id = df.factory_id
    WHERE te.factory_no = df.factory_no
);

COMMIT;